// src/config/index.ts
import dotenv from "dotenv";
dotenv.config();
function requiredEnv(key) {
  const value = process.env[key];
  if (!value) {
    throw new Error(`Missing required environment variable: ${key}`);
  }
  return value;
}
var config2 = {
  port: process.env.PORT || "5000",
  database_url: requiredEnv("DATABASE_URL"),
  jwt: {
    secret: requiredEnv("JWT_SECRET"),
    expiresIn: process.env.JWT_EXPIRES_IN || "2d"
  }
};
var config_default = config2;

// src/modules/auth/auth.service.ts
var createUser = async (payload) => {
  const hashPassword = await bcrypt.hash(payload.password, 8);
  const result = await prisma.user.create({
    data: {
      ...payload,
      password: hashPassword
    }
  });
  const { password, ...newPassword } = result;
  return newPassword;
};
var loginUser = async (payload) => {
  const user = await prisma.user.findUnique({
    where: {
      email: payload.email
    }
  });
  if (!user) {
    throw new Error("User not found");
  }
  const isPasswordMatched = await bcrypt.compare(
    payload.password,
    user.password
  );
  if (!isPasswordMatched) {
    throw new Error("Invalid credentials!!");
  }
  const userData = {
    id: user.id,
    name: user.name,
    role: user.role,
    email: user.email
  };
  const token = jwt2.sign(userData, config_default.jwt.secret, {
    expiresIn: config_default.jwt.expiresIn
  });
  const { password, ...safeUser } = user;
  return {
    token,
    user: safeUser
  };
};
var getMe = async (userId) => {
  const result = await prisma.user.findUnique({
    where: {
      id: userId
    }
  });
  if (!result) {
    throw new Error("User not found!");
  }
  const { password, ...safeUser } = result;
  return safeUser;
};
var AuthService = {
  createUser,
  loginUser,
  getMe
};

