// src/modules/tutor/tutor.service.ts
var createOrUpdateProfile = async (userId, payload) => {
  if (!userId) {
    throw new Error("User ID NOT EXISTS!");
  }
  const tutorData = {
    bio: payload.bio,
    expertise: payload.expertise,
    hourlyRate: payload.hourlyRate,
    experience: payload.experience
  };
  const existingProfile = await prisma.tutor.findUnique({
    where: { userId }
  });
  if (existingProfile) {
    const updated = await prisma.tutor.update({
      where: { userId },
      data: tutorData
    });
    return updated;
  }
  const created = await prisma.tutor.create({
    data: {
      userId,
      ...tutorData
    }
  });
  return created;
};
var getProfileByUserId = async (userId) => {
  const profile = await prisma.tutor.findUnique({
    where: { userId },
    include: {
      user: true,
      courses: true,
      bookings: true,
      reviews: true
    }
  });
  if (!profile) {
    throw new Error("Tutor profile not fond");
  }
  return profile;
};
var getAllTutors = async () => {
  return await prisma.tutor.findMany({
    include: {
      user: true,
      courses: true,
      reviews: true
    }
  });
};
var TutorService = {
  createOrUpdateProfile,
  getProfileByUserId,
  getAllTutors
};

